<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/auth.php';require_once __DIR__.'/_helper.php';bk_require_access($pdo);
if(user_role()==='kepala_sekolah'){http_response_code(403);exit('Detail layanan BK tidak tersedia untuk role Kepala Sekolah.');}
$id=max(0,(int)($_GET['id']??0));if($id<=0){http_response_code(404);exit('Layanan tidak ditemukan.');}
$sql="SELECT bl.*,s.nis,s.nisn,s.nama AS siswa_nama,mk.nama AS kelas,g.nama AS petugas FROM bk_layanan bl JOIN siswa s ON s.id=bl.siswa_id LEFT JOIN master_kelas mk ON mk.id=bl.kelas_id LEFT JOIN guru g ON g.id=bl.petugas_id WHERE bl.id=? LIMIT 1";$st=$pdo->prepare($sql);$st->execute([$id]);$r=$st->fetch();if(!$r){http_response_code(404);exit('Layanan tidak ditemukan.');}
if(user_role()==='guru_bk' && (int)$r['petugas_id']!==bk_current_guru_id($pdo)){http_response_code(403);exit('Akses detail layanan BK ditolak.');}
$page_title='Detail Layanan BK';require_once __DIR__.'/../layouts/header.php';require_once __DIR__.'/../layouts/sidebar.php';
?>
